//! spotlight_window
//! Topmost floating Spotlight search bar window with global hotkey support.
//!
//! Windows: DirectComposition layered window centered at 25% screen top,
//! global hotkey (Alt+Space), automatic kill-focus dismissal, and keyboard navigation.
//! Non-Windows: High-fidelity mock window for unit testing and development.

use std::collections::VecDeque;

/// Events generated by user interaction with Spotlight.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SpotlightEvent {
    Opened,
    Closed,
    QueryChanged(String),
    Execute,
    Navigate(i32), // -1 for Up, +1 for Down
    Escaped,
    ClickResult(String),
    Paint,
    DisplayChanged,
    Error(String),
}

/// Configuration for Spotlight floating window.
#[derive(Debug, Clone, PartialEq)]
pub struct SpotlightWindowConfig {
    pub width: u32,
    pub resting_height: u32,
    pub max_height: u32,
    pub title: String,
    pub class_name: String,
}

impl Default for SpotlightWindowConfig {
    fn default() -> Self {
        Self {
            width: 640,
            resting_height: 56,
            max_height: 420,
            title: "Spotlight".to_string(),
            class_name: "MacWinLauncherSpotlightClass".to_string(),
        }
    }
}

// ---------------------------------------------------------------------------
// Windows Implementation (DirectComposition Floating Search Bar)
// ---------------------------------------------------------------------------

#[cfg(windows)]
mod win32 { pub use crate::spotlight_native::NativeSpotlightWindow as Win32SpotlightWindow; }

// ---------------------------------------------------------------------------
// Cross-Platform Mock Implementation
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub struct MockSpotlightWindow {
    config: SpotlightWindowConfig,
    is_visible: bool,
    current_height: u32,
    query: String,
    selected_index: usize,
    events: VecDeque<SpotlightEvent>,
}

impl MockSpotlightWindow {
    pub fn new(config: SpotlightWindowConfig) -> Self {
        Self {
            current_height: config.resting_height,
            config,
            is_visible: false,
            query: String::new(),
            selected_index: 0,
            events: VecDeque::new(),
        }
    }

    pub fn show(&mut self) {
        if !self.is_visible {
            self.is_visible = true;
            self.events.push_back(SpotlightEvent::Opened);
        }
    }

    pub fn hide(&mut self) {
        if self.is_visible {
            self.is_visible = false;
            self.reset_query();
            self.reset_height();
            self.events.push_back(SpotlightEvent::Closed);
        }
    }

    pub fn toggle(&mut self) {
        if self.is_visible {
            self.hide();
        } else {
            self.show();
        }
    }

    pub fn is_visible(&self) -> bool {
        self.is_visible
    }

    pub fn poll_events(&mut self) -> Vec<SpotlightEvent> {
        self.events.drain(..).collect()
    }

    pub fn push_event(&mut self, event: SpotlightEvent) {
        self.events.push_back(event);
    }

    pub fn width(&self) -> u32 {
        self.config.width
    }

    pub fn height(&self) -> u32 {
        self.current_height
    }

    pub fn set_height(&mut self, height: u32) {
        self.current_height = height.clamp(self.config.resting_height, self.config.max_height);
    }

    pub fn reset_height(&mut self) {
        self.current_height = self.config.resting_height;
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn set_query(&mut self, q: impl Into<String>) {
        self.query = q.into();
        self.events
            .push_back(SpotlightEvent::QueryChanged(self.query.clone()));
    }

    pub fn reset_query(&mut self) {
        self.query.clear();
        self.selected_index = 0;
    }

    pub fn selected_index(&self) -> usize {
        self.selected_index
    }

    pub fn set_selected_index(&mut self, idx: usize) {
        self.selected_index = idx;
    }
}

// ---------------------------------------------------------------------------
// Unified SpotlightWindow Wrapper
// ---------------------------------------------------------------------------

enum SpotlightWindowInner {
    #[cfg(windows)]
    Real(win32::Win32SpotlightWindow),
    Mock(MockSpotlightWindow),
}

/// Unified Spotlight window presenting identical interfaces across platforms.
pub struct SpotlightWindow {
    inner: SpotlightWindowInner,
}

impl SpotlightWindow {
    /// Creates a mock Spotlight window for testing and development.
    pub fn new_mock() -> Self {
        Self {
            inner: SpotlightWindowInner::Mock(MockSpotlightWindow::new(SpotlightWindowConfig::default())),
        }
    }

    /// Creates a new Spotlight window with default config.
    pub fn new() -> Result<Self, String> {
        #[cfg(windows)]
        {
            let win = win32::Win32SpotlightWindow::new(SpotlightWindowConfig::default())?;
            Ok(Self { inner: SpotlightWindowInner::Real(win) })
        }
        #[cfg(not(windows))]
        {
            Ok(Self {
                inner: SpotlightWindowInner::Mock(MockSpotlightWindow::new(SpotlightWindowConfig::default())),
            })
        }
    }

    pub fn show(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.show(),
            SpotlightWindowInner::Mock(w) => w.show(),
        }
    }

    pub fn hide(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.hide(),
            SpotlightWindowInner::Mock(w) => w.hide(),
        }
    }

    pub fn toggle(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.toggle(),
            SpotlightWindowInner::Mock(w) => w.toggle(),
        }
    }

    pub fn is_visible(&self) -> bool {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.is_visible(),
            SpotlightWindowInner::Mock(w) => w.is_visible(),
        }
    }

    pub fn poll_events(&mut self) -> Vec<SpotlightEvent> {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.poll_events(),
            SpotlightWindowInner::Mock(w) => w.poll_events(),
        }
    }

    pub fn push_event(&mut self, event: SpotlightEvent) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.push_event(event),
            SpotlightWindowInner::Mock(w) => w.push_event(event),
        }
    }

    pub fn width(&self) -> u32 {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.width(),
            SpotlightWindowInner::Mock(w) => w.width(),
        }
    }

    pub fn height(&self) -> u32 {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.height(),
            SpotlightWindowInner::Mock(w) => w.height(),
        }
    }

    pub fn set_height(&mut self, height: u32) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.set_height(height),
            SpotlightWindowInner::Mock(w) => w.set_height(height),
        }
    }

    pub fn reset_height(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.reset_height(),
            SpotlightWindowInner::Mock(w) => w.reset_height(),
        }
    }

    pub fn query(&self) -> String {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.query(),
            SpotlightWindowInner::Mock(w) => w.query().to_string(),
        }
    }

    pub fn selected_index(&self) -> usize {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.selected_index(),
            SpotlightWindowInner::Mock(w) => w.selected_index(),
        }
    }

    pub fn set_selected_index(&mut self, idx: usize) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.set_selected_index(idx),
            SpotlightWindowInner::Mock(w) => w.set_selected_index(idx),
        }
    }

    pub fn hwnd(&self) -> isize {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.hwnd().0 as isize,
            SpotlightWindowInner::Mock(_) => 0,
        }
    }
}
